INSERT INTO `wp_posts` VALUES (1,0,'2026-07-16 20:02:11','2026-07-16 20:02:11','','Placeholder','','inherit','open','closed','','placeholder','','','2026-07-16 20:02:11','2026-07-16 20:02:11','',0,'http://art4development.local/wp-content/uploads/2026/07/05-placeholder.jpg',0,'attachment','image/jpeg',0),(100,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art is how we learn, heal, and change the world.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Arts for Global Development (Art4Development.Net) is an international learning nonprofit that harnesses the power of the arts and culture to advance social, ecological, and economic development and foster meaningful global-local collaboration and placemaking.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Our Purpose</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Since 2002, we have been connecting artists, development practitioners, researchers, educators, and communities across the world through creative inquiry, participatory programs, and knowledge exchange. We believe that lasting, inclusive change only happens when culture sits at the center.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>Development, local or global, succeeds or fails in the cultural space. Art4Development.Net makes that space visible.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Three Ways to Engage</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Explore What We Do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Consulting, placemaking, research, and design programs that put the arts and culture to work.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Take Action</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Join an initiative, attend an event, or contribute to our global learning community.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Champion the Work</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Partner with us, donate, or volunteer your time and expertise.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Why Art?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Throughout history, the arts have been one of humanity&#x27;s most universal connectors—transcending education levels, socio-political and economic status, age, ethnicity, race, religion, gender, sexual orientation, and culture. The arts help simplify complexity, inspire creativity, surface new perspectives, build empathy, and generate the kind of insight that drives meaningful change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>At Art4Development.Net, we harness that power with intention: co-creating arts-led and arts-infused programs, and facilitating spaces where people connect, collaborate, and build solutions that matter most to their communities.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This is not art as decoration. This is art as a catalyst.</p>\n<!-- /wp:paragraph -->','Home','','publish','closed','closed','','home','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=100',0,'page','',0),(110,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Arts for Global Development is an international learning nonprofit that harnesses the power of the arts and culture to advance social, ecological, and economic development.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Learn more about our story, our promises, our team, and what we do.</p>\n<!-- /wp:paragraph -->','About','','publish','closed','closed','','about','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=110',10,'page','',0),(111,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Our Story</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Arts for Global Development (Art4Development.Net) was founded in 2002 by Nil Şişmanyazıcı-Navaie, driven by a simple but urgent conviction: that the arts and culture are essential—not decorative—to how we build a more just, sustainable, and creative world.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>What began as an early online community connecting artists and development practitioners across borders has grown into an international learning nonprofit spanning exhibitions, publications, consulting, and creative placemaking. From a listserv of curious minds in the early 2000s to a global network of collaborators, our story is one of quiet, patient, cross-disciplinary work—always in service of communities and creative practitioners.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We are a registered 501(c)3 educational nonprofit, entirely volunteer-led since our founding.</p>\n<!-- /wp:paragraph -->','Who We Are','','publish','closed','closed','','who-we-are','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',110,'https://art4development.net/?page_id=111',10,'page','',0),(112,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Our Story</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Arts for Global Development (Art4Development.Net) was founded in 2002 by Nil Şişmanyazıcı-Navaie, driven by a simple but urgent conviction: that the arts and culture are essential—not decorative—to how we build a more just, sustainable, and creative world.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>What began as an early online community connecting artists and development practitioners across borders has grown into an international learning nonprofit spanning exhibitions, publications, consulting, and creative placemaking. From a listserv of curious minds in the early 2000s to a global network of collaborators, our story is one of quiet, patient, cross-disciplinary work—always in service of communities and creative practitioners.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We are a registered 501(c)3 educational nonprofit, entirely volunteer-led since our founding.</p>\n<!-- /wp:paragraph -->','Our Story','','publish','closed','closed','','our-story','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',111,'https://art4development.net/?page_id=112',10,'page','',0),(113,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Everything we do rests on three commitments—to people, to the planet, and to the meaningful performance and prosperity of the communities we work with.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">People</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We center human dignity, cultural knowledge, and lived experience in every program. Our work amplifies underrepresented voices, invites intergenerational collaboration, and supports the health and wellbeing of artists and communities.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Planet</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We treat ecological wellbeing as inseparable from human wellbeing. Our programs address climate, water, food systems, and biodiversity through creative practice—and we make and source our own materials responsibly.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Performance &amp; Prosperity</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We measure success by the durability of the change we help create: artists better positioned to sustain their practice, communities equipped with new tools and networks, and evidence that expands what&#x27;s possible in the field.</p>\n<!-- /wp:paragraph -->','Our Promise','','publish','closed','closed','','our-promise','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',111,'https://art4development.net/?page_id=113',20,'page','',0),(114,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art4Development.Net has always been powered by people who believe in the work. Our board of directors, advisory board, and volunteer team bring together expertise from across the arts, research, strategic communications, education, design, technology, and global development.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Meet the people behind Art4Development.Net. This page displays entries from the Team Member custom post type, grouped by role.</p>\n<!-- /wp:paragraph -->','Our Team','','publish','closed','closed','','our-team','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',111,'https://art4development.net/?page_id=114',30,'page','',0),(115,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art4Development.Net is, at its core, a learning organization. Our work spans four interconnected areas—each one a way of putting the arts and culture to work for social, ecological, and economic change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Consulting</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Program design, cultural strategy, and organizational support for mission-driven partners.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Creative Placemaking &amp; Experience</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Arts-infused environments, exhibitions, and public experiences that spark connection and dialogue.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Creative Intel</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Research, curation, publications, and knowledge exchange at the intersection of arts and development.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Design Lab</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Tangible, arts-infused tools and products co-created with communities and designed with purpose.</p>\n<!-- /wp:paragraph -->','What We Do','','publish','closed','closed','','what-we-do','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',110,'https://art4development.net/?page_id=115',20,'page','',0),(116,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art4Development.Net&#x27;s consulting practice helps mission-driven organizations put the arts and culture to work. Drawing on more than two decades of cross-sector, cross-cultural collaboration, we design programs, shape strategy, and support organizational development at the intersection of creativity, sustainability, and social impact.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">What we do</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Program design and evaluation for cultural, educational, and development initiatives</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Strategic advising on how to integrate arts and culture into organizational missions and communications</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Cross-sector partnership brokering, especially where the arts meet health, sustainability, urban planning, and education</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Organizational capacity building for artists, cultural collectives, and small nonprofits</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We work with a wide range of partners—from grassroots collectives to large development agencies—and we tailor engagements to fit context, scale, and budget.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Let&#x27;s talk about your project →</p>\n<!-- /wp:paragraph -->','Consulting','','publish','closed','closed','','consulting','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',115,'https://art4development.net/?page_id=116',10,'page','',0),(117,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Creative placemaking is how we bring the arts into public life. We design and produce arts-infused environments, exhibitions, and experiences that invite people to engage with ideas, each other, and the places they inhabit.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Our approach spans</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Curation of exhibitions and public art programs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Arts program design and installation for corporate, nonprofit, and public spaces</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Interactive workshop design for diverse audiences (from school-age children to global development leaders)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Gallery talks, panel discussions, and community gatherings</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Conference and convening arts experiences that turn passive audiences into active participants</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Virtual safe places for connection and healing integrating arts therapy</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We work with partners to find the right form for the right moment, because the space between a person and a work of art, in any form or discipline, is where change begins.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Let&#x27;s design something together →</p>\n<!-- /wp:paragraph -->','Creative Placemaking & Experience','','publish','closed','closed','','placemaking','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',115,'https://art4development.net/?page_id=117',20,'page','',0),(118,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art4Development.Net is, at its core, a learning organization. We research, experiment, generate, curate, and share knowledge at the intersection of arts, culture, and development—building the evidence base that helps practitioners, policymakers, and educators make the case for creativity as a driver of change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Our Creative Intel work encompasses</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Original research, analysis, and published opinion on the role of arts in development</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Commissioned reports and interdisciplinary writing on SDG-aligned themes</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Curation of our art&#x27;ishake e-magazine, covering global arts-and-development topics across disciplines</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>A growing library of resources, case studies, and knowledge-exchange materials</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Speaking engagements, panel contributions, and public lectures at conferences worldwide</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We have contributed to conversations at institutions including Popular Culture Association, the Global Health Council, the Association for Cultural Economics International, King&#x27;s College London, Columbia College Chicago, and the University of Maryland. Our writing has been featured in international publications and commissioned by bodies including the Committee on Culture of United Cities and Local Governments (UCLG).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We share what we learn because we believe knowledge is a public good, and that interdisciplinary, holistic understanding leads to more thoughtful and effective action.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Explore our research and publications →</p>\n<!-- /wp:paragraph -->','Creative Intel','','publish','closed','closed','','creative-intel','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',115,'https://art4development.net/?page_id=118',30,'page','',0),(119,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>The Design Lab is where we prototype, make, and celebrate. It is the creative studio of Art4Development.Net—a space for designing tangible, arts-infused tools and products that educate, inspire, and generate impact.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Everything we develop in the Design Lab is co-created with communities, guided by purpose, and designed to be as kind to the planet as it is useful to people. Our offerings range from educational games and bilingual publications to eco-friendly craft kits and upcycled promotional goods.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Current Design Lab offerings include</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Lili&#x27;s Alphabet Book &amp; Game — A bilingual Turkish-English literacy tool for children ages 4–12. Sales proceeds support girls&#x27; education and early childhood programs in underserved communities in Turkey.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>The Spoon Puppet Kit — An eco-friendly arts and crafts kit that teaches children about soil health and sustainable food systems through storytelling and play in the US.</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Upcycled Promotional Goods (in partnership with The Revival, Ghana) — Sustainable, community-made alternatives to conventional conference giveaways, expanding market access for artisans from the Global South.</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>If you create eco-friendly educational tools, purposeful objects, or arts-based learning materials that align with our mission, we&#x27;d love to explore what we might build together.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Visit the Design Lab →</p>\n<!-- /wp:paragraph -->','Design Lab','','publish','closed','closed','','design-lab','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',115,'https://art4development.net/?page_id=119',40,'page','',0),(120,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art provokes. It asks questions that are hard to ask any other way. It makes us listen to voices other than our own, sit with complexity, and find the courage to act. Everything Art4Development.Net does is designed to move people from awareness to engagement—and from engagement to impact.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Here&#x27;s how you can be part of it.</p>\n<!-- /wp:paragraph -->','Take Action','','publish','closed','closed','','take-action','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=120',20,'page','',0),(121,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Our events are designed to do more than inform—they are built to spark genuine dialogue, deepen understanding, and inspire action. From intimate gallery talks to large-scale conference programs, every gathering is an opportunity to explore what happens when art, ideas, and people come together.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">What we help facilitate and co-produce</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Gallery talks and panel discussions</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Public exhibitions and community art programs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Convenings, workshops, and cross-sector dialogues</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Speaker series and cultural programming for partner conferences</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Youth arts festivals, family programs, and workshops</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Recent events have brought together artists, humanitarian advocates, architects, scientists, educators, and policymakers around themes including identity and inclusion, women&#x27;s healing and wellbeing, environmental sustainability, water and climate, and peacebuilding and resilience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>See our full recent programming across socio-cultural, economic, and environmental themes on our Initiatives page.</p>\n<!-- /wp:paragraph -->','Events','','publish','closed','closed','','events','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',120,'https://art4development.net/?page_id=121',10,'page','',0),(122,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Our initiatives are how we put our mission into practice—as ongoing, evolving arts-led projects that bring together communities, artists, practitioners, and partners around shared work.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Explore our current and ongoing initiatives below. This page displays entries from the Initiative custom post type.</p>\n<!-- /wp:paragraph -->','Initiatives','','publish','closed','closed','','initiatives','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',120,'https://art4development.net/?page_id=122',20,'page','',0),(123,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Knowledge is the foundation of everything we do. Our Research &amp; Exchange programs create space for rigorous inquiry, collaborative learning, and the kind of candid conversation that moves ideas into action.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This is where artists, academics, practitioners, and advocates come together as equals—contributing to a body of knowledge that is interdisciplinary, globally informed, and community-grounded.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">The e-Community</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>From 2002 through the mid-2010s, Art4Development.Net built one of the earliest interdisciplinary online communities dedicated to arts-led social impact: connecting over 1,300 members from more than 80 countries through hundreds of knowledge-exchange e-digests covering topics from cultural heritage and theatre for development to DigiArts and music for peacebuilding. That spirit of open, cross-disciplinary dialogue continues to shape everything we do.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Open Calls &amp; Submissions</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We regularly invite contributions from artists, researchers, writers, and practitioners whose work intersects with our program areas. Current open calls include:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>art&#x27;ishake submissions (rolling — see Publications)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Artist applications for DC/MD/VA exhibition program (&quot;Gotta Story to Tell&quot; — rolling)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>CreativeChange+ impact story submissions (ongoing) — inviting artists and creative organizations worldwide to share impact stories.</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Speaking &amp; Convening</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Art4Development.Net has been invited to share insights at conferences, universities, and global forums worldwide—including the Global Health Council, the Association for Cultural Economics International, King&#x27;s College London, the University of Maryland, and the International Humanitarian Aid and Development Conference in Dubai. We are available to contribute to your events as speakers, facilitators, and program designers.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Invite us to your convening →</p>\n<!-- /wp:paragraph -->','Research & Exchange','','publish','closed','closed','','research-exchange','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',120,'https://art4development.net/?page_id=123',30,'page','',0),(130,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>We believe that knowledge, when shared openly, becomes a tool for change. Our publications bring together research, interdisciplinary perspectives, artist voices, and practical insights at the intersection of arts, culture, and development.</p>\n<!-- /wp:paragraph -->','Publications','','publish','closed','closed','','publications','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=130',30,'page','',0),(131,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>art&#x27;ishake is Art4Development.Net&#x27;s interdisciplinary e-magazine—a platform where artists, researchers, practitioners, and educators share perspectives, practices, and provocations from across the globe.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Each issue explores arts from an interdisciplinary lens, weaving together stories, artworks, case studies, opinion pieces, and practical &quot;how-tos&quot; that illuminate the role of creativity in addressing the world&#x27;s most pressing challenges. The publication covers issues aligned with the Sustainable Development Goals (SDGs), with a focus on placemaking, identity, environmental resilience, and the essentials of everyday life—clothing, shelter, food, health, education, and voice.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The latest issue highlights textile arts and sustainability. Request your free copy →</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We welcome submissions from artists, writers, researchers, and practitioners on a rolling basis. We are looking for papers, visual work, poetry, case studies, reflections, and other content that contributes knowledge, sparks dialogue, and inspires creative change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Submit to art&#x27;ishake →</p>\n<!-- /wp:paragraph -->','art\'ishake','','publish','closed','closed','','artishake','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',130,'https://art4development.net/?page_id=131',10,'page','',0),(132,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Our Library is a curated collection of research, reports, articles, and knowledge-exchange materials produced by Art4Development.Net and our collaborators over more than two decades of work.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Individual publications appear below as entries from the Publication custom post type. Browse by type or search for specific topics.</p>\n<!-- /wp:paragraph -->','Library','','publish','closed','closed','','library','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',130,'https://art4development.net/?page_id=132',20,'page','',0),(140,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>For over two decades, Art4Development.Net has been entirely volunteer-led. The work we do—connecting artists with opportunity, embedding creativity into development programs, building knowledge, and activating communities—happens because people who believe in it choose to show up and contribute.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are many ways to be part of this. We invite you to find yours.</p>\n<!-- /wp:paragraph -->','Champion the Work','','publish','closed','closed','','champion','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=140',40,'page','',0),(141,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Organizational partnerships are at the heart of how Art4Development.Net scales its impact. We partner with academic institutions, cultural organizations, development agencies, foundations, and purpose-driven businesses who share our commitment to creativity as a catalyst for change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">What does partnership look like?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Co-designing and co-funding programs that align with your mission, ESG commitments, or SDG priorities</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Hosting exhibitions, workshops, or learning experiences in your spaces</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Embedding art-based approaches into your conferences, convenings, or community programs</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Developing arts program curation and long-term exhibition partnerships for corporate or institutional spaces</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Sponsoring specific initiatives—from CreativeChange and Project H2O to art&#x27;ishake and the Design Lab</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We work with partners to build creative strategies that are both meaningful and measurable. Whether you are a large institution or a small community organization, there is a way to collaborate.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Let&#x27;s talk →</p>\n<!-- /wp:paragraph -->','Invest & Partner','','publish','closed','closed','','invest-partner','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',140,'https://art4development.net/?page_id=141',10,'page','',0),(142,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Your financial support makes the work possible. Art4Development.Net is a registered 501(c)3 nonprofit, and every contribution—of any size—goes directly toward programs that create opportunity for artists, generate knowledge for the field, and deliver creative experiences to communities that need them most.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">You can support us by</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Making a one-time or recurring donation</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Sponsoring a specific program, exhibition, or event</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Purchasing Design Lab products, where proceeds support our educational initiatives</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Bidding in our online auctions (such as the Project H2O auction supporting clean water access)</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Art4Development.Net is a space where every dollar is matched by extraordinary volunteer effort. You are not just funding programs—you are multiplying impact.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Donate now →</p>\n<!-- /wp:paragraph -->','Donate & Sponsor','','publish','closed','closed','','donate-sponsor','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',140,'https://art4development.net/?page_id=142',20,'page','',0),(143,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Art4Development.Net has always been powered by people who believe in the work. Our team of volunteers and advisers brings together expertise from across the arts, research, strategic communications, education, design, technology, and global development.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We welcome volunteers and interns who want to contribute their skills and grow through meaningful, mission-aligned work. Opportunities include:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Research, writing, and publications support (including art&#x27;ishake)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Event planning and program coordination</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Social media, digital communications, and outreach</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Exhibition curation and arts program support</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Design, photography, and visual storytelling</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Fundraising and development support</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Whether you are a student looking for field experience or a seasoned professional who wants to put your skills toward something meaningful—there is a place for you here.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Join our team →</p>\n<!-- /wp:paragraph -->','Volunteer & Intern','','publish','closed','closed','','volunteer-intern','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',140,'https://art4development.net/?page_id=143',30,'page','',0),(150,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>We&#x27;d love to hear from you—whether you&#x27;re an artist, a potential partner, a researcher, a donor, or simply someone who believes in the power of the arts to change the world.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Reach out to us at: info [at] art4development.net</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You can also use the form below to tell us a bit about yourself and what brings you here. We read every message.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">I&#x27;m reaching out about...</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\">\n<!-- wp:list-item -->\n<li>Viewing the exhibition at InterAction</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Attending or hosting an event</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>A program or project partnership</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Consulting and creative strategy</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Contributing to art&#x27;ishake or the Library</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Design Lab products or upcycled promo goods</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Volunteering or interning</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Donating or sponsoring</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Something else — tell us more</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Follow us on Instagram and LinkedIn to stay connected with our work, events, and open calls.</p>\n<!-- /wp:paragraph -->','Contact','','publish','closed','closed','','contact','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?page_id=150',50,'page','',0),(300,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>A multimedia group exhibition exploring how identity, place, and collective care shape the futures we are building together. Currently on view at InterAction, Washington DC (through May 31, 2026), featuring local and international artists working across diverse media on social and environmental themes. New works added in 2026 reflect evolving stories of resilience and belonging. All artworks are for sale, supporting various ongoing social and environmental programs.</p>\n<!-- /wp:paragraph -->','Resilience & Reverberation','A multimedia group exhibition on identity, place, and collective care.','publish','closed','closed','','resilience-reverberation','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=initiative&amp;p=300',0,'initiative','',0),(301,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Now celebrating its 20th anniversary, CreativeChange is Art4Development.Net&#x27;s flagship arts initiative, exploring what becomes possible when communities leverage the power of arts and create together for social and ecological change.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>From visual art to immersive soundscapes created by sound engineers and musicians, CreativeChange brings together multiple art forms to create multisensory experiences that illuminate lived realities, spark empathy and reflection, and inspire action. Since 2005, CreativeChange exhibitions and programs have traveled to venues across the United States, Canada, Nigeria, Cameroon, Macedonia, and Dubai.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As part of this milestone edition, we are inviting artists and creative organizations worldwide to share impact stories and join a global celebration of creativity, resilience, and collective imagination.</p>\n<!-- /wp:paragraph -->','CreativeChange+','Our flagship arts initiative — now celebrating 20 years.','publish','closed','closed','','creativechange-plus','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=initiative&amp;p=301',0,'initiative','',0),(302,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>This initiative looks at how everything is connected—soil, land, biodiversity, planetary health, human wellbeing, and the systems that feed us.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You might be wondering: what does art have to do with all of this? A lot more than you&#x27;d think.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The project responds to real-world challenges like rapid urban growth, rural-to-urban migration, and rising food insecurity. At the same time, it explores creative possibilities, like urban farming, regenerative ways of living, and building stronger, more connected communities through the arts.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>RurbanArts brings this to life through a mix of an international miniature art exhibition and hands-on family and youth activities. This includes the Mr. Shovel &amp; Ms. Spoon workshop series, where participants learn through making, exploring food, sustainability, and healthy living in a fun and creative way.</p>\n<!-- /wp:paragraph -->','RurbanArts','How everything is connected — soil, land, biodiversity, planetary health, and the systems that feed us.','publish','closed','closed','','rurbanarts','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=initiative&amp;p=302',0,'initiative','',0),(303,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>A growing arts initiative at the intersection of creativity and water justice. Project H2O brings together artists from across the world to explore water—its scarcity, its power, its cultural meaning, and its future.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The initiative includes a virtual exhibition, artwork sales supporting clean water access in collaboration with Bridge H2OPE, in-person community conversations, and ongoing dialogue with artists and sustainability experts to find ways to make a positive impact.</p>\n<!-- /wp:paragraph -->','Project H2O: Stories of Water','A growing arts initiative at the intersection of creativity and water justice.','publish','closed','closed','','project-h2o','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=initiative&amp;p=303',0,'initiative','',0),(304,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>In partnership with the &quot;We Make Tomorrow&quot; global campaign, Art4Development.Net has been amplifying the call for culture to be recognized as an essential pillar of climate action.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We are now getting ready for COP31. Interested in collaborating with us?</p>\n<!-- /wp:paragraph -->','COP# Culture Campaign','Amplifying the call for culture to be recognized as an essential pillar of climate action.','publish','closed','closed','','cop-culture-campaign','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=initiative&amp;p=304',0,'initiative','',0),(400,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Nil S. Navaie, Founder and Director of Arts for Global Development, is a strategist, mixed-media artist, and author whose work operates at the intersection of culture, sustainability, health, and social impact. Drawing on over 20 years of international experience, she designs and leads cross-sector collaborations that connect local action with global dialogue, using creativity as a catalyst for positive human and ecological development.</p>\n<!-- /wp:paragraph -->','Nil S. Navaie','Nil S. Navaie, Founder and Director of Arts for Global Development, is a strategist, mixed-media artist, and author whose work operates at the intersection of culture, sustainability, health, and soci','publish','closed','closed','','nil-navaie','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=400',10,'team_member','',0),(401,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Elif Ertem is a global marketing executive with nearly 30 years of experience leading brand, customer engagement, and growth strategies for international Fortune 500 companies. As a founding board member, she provides strategic guidance on storytelling, communications, and organizational development.</p>\n<!-- /wp:paragraph -->','Elif Ertem','Elif Ertem is a global marketing executive with nearly 30 years of experience leading brand, customer engagement, and growth strategies for international Fortune 500 companies. As a founding board mem','publish','closed','closed','','elif-ertem','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=401',20,'team_member','',0),(402,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Sabi Behzadi is a management consultant and social entrepreneur with extensive experience in global strategy, public policy, and cross-cultural partnerships across more than a dozen countries. She brings expertise in international collaboration and social innovation to the board.</p>\n<!-- /wp:paragraph -->','Sabi Behzadi','Sabi Behzadi is a management consultant and social entrepreneur with extensive experience in global strategy, public policy, and cross-cultural partnerships across more than a dozen countries. She bri','publish','closed','closed','','sabi-behzadi','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=402',30,'team_member','',0),(403,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Kia Navaie is a technology leader specializing in healthcare IT, data infrastructure, and AI-driven systems integration. As a founding board member, he provides technical leadership, financial oversight, and operational support for the organization&#x27;s programs and exhibitions.</p>\n<!-- /wp:paragraph -->','Kia Navai','Kia Navaie is a technology leader specializing in healthcare IT, data infrastructure, and AI-driven systems integration. As a founding board member, he provides technical leadership, financial oversig','publish','closed','closed','','kia-navai','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=403',40,'team_member','',0),(404,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Melda Değirmenci is an attorney with distinguished experience advising global financial institutions on complex cross-border finance and restructuring matters. Her legal expertise and commitment to community service strengthen the organization&#x27;s governance and strategic planning.</p>\n<!-- /wp:paragraph -->','Melda Değirmenci','Melda Değirmenci is an attorney with distinguished experience advising global financial institutions on complex cross-border finance and restructuring matters. Her legal expertise and commitment to co','publish','closed','closed','','melda-degirmenci','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=404',50,'team_member','',0),(405,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Paul Guise is a cultural consultant, music educator, and researcher who helps artists and cultural organizations build sustainable and impactful practices. His work combines business analytics, curriculum development, and creative leadership to support the cultural sector.</p>\n<!-- /wp:paragraph -->','Paul Guise','Paul Guise is a cultural consultant, music educator, and researcher who helps artists and cultural organizations build sustainable and impactful practices. His work combines business analytics, curric','publish','closed','closed','','paul-guise','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=405',10,'team_member','',0),(406,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Teresa Diaz is an arts leader, curator, and educator with expertise in Latin American art, community engagement, and cultural programming. Through her work in galleries, museums, and philanthropy, she advances the role of the arts in education and social impact.</p>\n<!-- /wp:paragraph -->','Teresa Diaz','Teresa Diaz is an arts leader, curator, and educator with expertise in Latin American art, community engagement, and cultural programming. Through her work in galleries, museums, and philanthropy, she','publish','closed','closed','','teresa-diaz','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=406',20,'team_member','',0),(407,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Emon Surakitkoson is a Thai-born artist whose work explores identity, memory, and cross-cultural experience through painting and sculpture. She brings a unique artistic perspective and commitment to global understanding through creativity and cultural exchange.</p>\n<!-- /wp:paragraph -->','Emon Surakitkoson','Emon Surakitkoson is a Thai-born artist whose work explores identity, memory, and cross-cultural experience through painting and sculpture. She brings a unique artistic perspective and commitment to g','publish','closed','closed','','emon-surakitkoson','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=407',30,'team_member','',0),(408,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Thuli Wolf is a physician, artist, and art therapist who advocates for the role of creativity in health and well-being. Through her clinical, artistic, and educational work, she helps individuals and communities harness the transformative power of creative expression.</p>\n<!-- /wp:paragraph -->','Thuli Wolf','Thuli Wolf is a physician, artist, and art therapist who advocates for the role of creativity in health and well-being. Through her clinical, artistic, and educational work, she helps individuals and ','publish','closed','closed','','thuli-wolf','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=team_member&amp;p=408',40,'team_member','',0),(500,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Including the CreativeChange online study and the concept whitepaper on Creative Social Entrepreneurship.</p>\n<!-- /wp:paragraph -->','The Creative Change e-Report','Including the CreativeChange online study and the concept whitepaper on Creative Social Entrepreneurship.','publish','closed','closed','','creative-change-e-report','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=publication&amp;p=500',0,'publication','',0),(501,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>A Brief Overview of Culture and Sustainable Local Development with a Focus on Public-Private Sector Synergies. Commissioned work for the Committee on Culture of United Cities and Local Governments (UCLG).</p>\n<!-- /wp:paragraph -->','Achieving MDGs with Local Creativity','A Brief Overview of Culture and Sustainable Local Development with a Focus on Public-Private Sector Synergies. Commissioned work for the Committee on Culture of United Cities and Local Governments (UCLG).','publish','closed','closed','','achieving-mdgs-with-local-creativity','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=publication&amp;p=501',0,'publication','',0),(502,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>Volume 1 Issue 2. Making the &#x27;arts&#x27; and &#x27;net&#x27; work to help achieve MDGs: An Art4Development.net story.</p>\n<!-- /wp:paragraph -->','UNESCO e-Journal of Multi-disciplinary Research in the Arts','Volume 1 Issue 2. Making the \'arts\' and \'net\' work to help achieve MDGs: An Art4Development.net story.','publish','closed','closed','','unesco-ejournal-2008','','','2026-07-09 13:37:17','2026-07-09 13:37:17','',0,'https://art4development.net/?post_type=publication&amp;p=502',0,'publication','',0),(503,2,'2026-07-09 13:37:17','2026-07-09 13:37:17','<!-- wp:paragraph -->\n<p>A publication highlighting youth voices and action on the Millennium Development Goals.</p>\n<!-- /wp:paragraph -->','Raising Their Voices','A pub